    quick_mock:      "Quick Mock",
    pre_exam:        "試験前チェック",
    practice:        "練習",
    review:          "復習",
    daily_challenge: "今日の 1 問",
    vocabuspeak:     "VocabuSpeak（英語）",
    manual_quiz:     "自分で作った問題",
