      source: "vocabuspeak",
      activity: str(o.activity) || "lesson",
      lessonId: str(o.lessonId) || undefined,
      scenarioId: str(o.scenarioId) || undefined,
      level: str(o.level) || "",
      categoryId: str(o.categoryId) || undefined,
