    showJapanese: true,
    speed: 1,
    voiceId: "",
    accent: "american",
    includeBeta: false,           /* 声を出す形式（未完成）を出すか */
    audioRetention: "immediate",  /* immediate / session / 7days / 30days */
    dailyGoalMinutes: 10
