        + ", body: [#" + qCall + "]"
        + ", figures: " + E.arr(figs)
        + ", gap: " + E.mm(rb.figure.gapMm)
        + ", body-width: " + E.pct(rb.figure.bodyWidthPct)
        + ", figure-width: " + E.pct(rb.figure.figureWidthPct)
