      + ", columns: " + E.num(rb.choice.columns, 1)
      + ", variant: " + E.str(rb.choice.variant)
      + ", size: " + E.pt(rb.bodySizePt)
      + ", indent: " + E.mm(rb.choice.indentMm)
      + ", marker-width: " + E.mm(rb.choice.markerWidthMm) + ")";
