      U.on(r, "click", '[data-act="pside-close"]', function () { st.sideOpen = false; render(); });
      U.on(r, "click", '[data-act="prev"]', function () { goto(st.index - 1); });
      U.on(r, "click", '[data-act="next"]', function () { goto(st.index + 1); });
