        try { st.slug = A.suggestSlug(st.title || meta.name); } catch (e) {}
        var box = r.querySelector('[data-key="slug"]');
        if (box) box.value = st.slug;
        st.checking = true; st.slugOk = false; st.slugMsg = "使えるか確認しています…";
