      U.on(r, "click", '[data-act="pickbanner"]', function () {
        pickImage("banner").then(function (u) { if (u) { st.banner = u; render(); } });
      });
      U.on(r, "click", '[data-act="pickicon"]', function () {
        pickImage("icon").then(function (u) { if (u) { st.iconImage = u; render(); } });
      });
      U.on(r, "click", '[data-act="clearbanner"]', function () { st.banner = ""; render(); });
      U.on(r, "click", '[data-act="clearicon"]', function () { st.iconImage = ""; render(); });
