    "padding:8px 14px;border-radius:999px;font:600 15px/1 ui-monospace,SFMono-Regular,Menlo,monospace;",
    "background:rgba(24,22,32,.86);color:#fff;backdrop-filter:blur(10px);",
    "-webkit-backdrop-filter:blur(10px);box-shadow:0 6px 22px rgba(0,0,0,.22);",
