        if (type === "area") {
          marks += '<path d="' + d + " L" + pts[pts.length - 1][0].toFixed(1) + " " + y(0).toFixed(1)
            + " L" + pts[0][0].toFixed(1) + " " + y(0).toFixed(1) + ' Z" fill="' + color(si) + '" opacity="0.18"/>';
        }
        marks += '<path d="' + d + '" fill="none" stroke="' + color(si)
