        + '<rect x="' + padL + '" y="' + y + '" width="' + w.toFixed(1) + '" height="' + (rowH - 7)
        + '" rx="3" fill="' + color(i) + '"><title>' + esc(labels[i] + ": " + fmt(num(v))) + "</title></rect>"
        + '<text x="' + (padL + w + 6) + '" y="' + (y + (rowH - 7) / 2)
