      var nps = Math.round(((prom - det) / nums.length) * 100);
      return { kind: "nps", n: nums.length, nps: nps,
        chart: { type: "bar", labels: ["批判者 0-6", "中立 7-8", "推奨者 9-10"],
          series: [{ name: "人数", values: [det, nums.length - det - prom, prom] }] },
        note: "NPS = " + nps };
