          if (条) style += 条.replace(/^;/, "") + ";";
          var 見 = "";
          try { 見 = fmtCell(v, st); } catch (e) { 見 = String(v == null ? "" : v); }
          /* 数式（$…$）も 紙で 組む。SVG なので 別窓でも そのまま 出る。 */
          var 中 = (root.VQWPM && root.VQWPM.式がある(見))
            ? root.VQWPM.素の文を描く(見) : esc(見);
          var タ = (r === 1 && st && st.b) ? "th" : "td";
          h += "<" + タ + (sp && sp.rs > 1 ? ' rowspan="' + sp.rs + '"' : "")
            + (sp && sp.cs > 1 ? ' colspan="' + sp.cs + '"' : "")
            + (style ? ' style="' + esc(style) + '"' : "") + ">" + 中 + "</" + タ + ">";
